{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello शिव प्रकाश जी आपको floor tiles की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "Hello."
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "नमस्ते।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "आपको floor tiles की requirement थी ना?"
    },
    {
      "i": 4,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "आपको कितने square feet चाहिए?"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "चार सौ ठीक है अब tile size के बारे में बात कर लेते हैं आपको दो by दो feet चाहिए या कुछ और?"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "बारह बाई बारह।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "अब tile type बताइए आप double charge GVT या कोई और prefer करेंगे?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "अटकन कुड़ी।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "Sorry आपकी आवाज़ clear नहीं आई ज़रा दोबारा बताइए कि आप कौन सा tile type prefer करेंगे?"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "अपन गुड़ी और एक।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "ठीक है आपको मैं seller details WhatsApp पे भेज दूँगी।"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "Okay thank you."
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "आपका दिन शुभ हो।"
    }
  ]
}
